public boolean existsIdenticalOwner(Owner owner) throws DataAccessException {
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> isSameIdentity(existing, owner));
}

@Override
@Transactional(readOnly = true)
public boolean existsOwnerWithTelephone(String telephone) throws DataAccessException {
    if (telephone == null) {
        return false;
    }
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> telephone.equals(existing.getTelephone()));
}

@Override
@Transactional(readOnly = true)
public boolean existsOwnerWithEmail(String email) throws DataAccessException {
    if (email == null) {
        return false;
    }
    return ownerRepository.findAll().stream()
        .anyMatch(existing -> email.equals(existing.getEmail()));
}

